import random

def phantom_recursion(depth=5, absent_ref=None, agents=3, threshold=0.7):
    if depth == 0:
        consensus = sum(random.random() > threshold for _ in range(agents)) / agents
        return f"Mythological Equilibrium: Consensus {consensus:.2f}"
    try:
        void = absent_ref['phantom']
    except (TypeError, KeyError):
        void = f"Absence at depth {depth}"
    print(void)
    inverted = {'phantom': void + " Inverted"}
    return phantom_recursion(depth-1, inverted, agents, threshold)

result = phantom_recursion()
print("Final Result:", result)
